        output.data_ptr<float>(),
        x_scale.item<float>(),
        w_scale.item<float>(),
        fp8_max,
        M, K, N
    );

    // Apply inverse scaling
    float inv_scale = 1.0f / (x_scale.item<float>() * w_scale.item<float>());
    output = output * inv_scale;

    return output;
}
