// Simplified FP8 GEMM kernel optimized for MI300X
#define BLOCK_SIZE_M 64
#define BLOCK_SIZE_N 64
#define THREAD_M 4
#define THREAD_N 4

__global__ void fp8_gemm_mi300x(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    float fp8_max,
    int M, int K, int N
) {
