    }

    // Store results
    #pragma unroll
    for(int i = 0; i < THREAD_M; i++) {
        #pragma unroll
        for(int j = 0; j < THREAD_N; j++) {
            if(global_m + i < M && global_n + j < N) {
                C[(global_m + i) * N + (global_n + j)] = accum[i][j];
            }
        }
    }
